public class TestMain {
    public static void main(String[] args) {
        String[][] cases = {
        {"Hello, <%name%>!", "name=Ada\ncity=Oslo", "Hello, Ada!"},
        {"<%city=nowhere%> / <%missing=none%>", "name=Ada", "nowhere / none"},
        {"<%name|caps%>", "name=Ada\ncity=Oslo", "ADA"},
        {"<%?flag%>on<%^%>off<%/%> <%-flag%>x<%/%>", "flag=1", "on "},
        {"<%*items%><%@%>=<%.%>; <%^%>nothing<%/%>", "items=ant,bee", "1=ant; 2=bee; "},
        };
        int failed = 0;
        for (int i = 0; i < cases.length; i++) {
            String[] c = cases[i];
            String want = c[2];
            String got;
            try {
                got = Template.render(c[0], c[1]);
            } catch (Throwable e) {
                got = "EXCEPTION " + e;
            }
            if (!want.equals(got)) {
                failed++;
                System.out.println("case " + i + " FAILED\n  args: " + String.join(" | ", java.util.Arrays.copyOf(c, 2)) + "\n  got:  " + got + "\n  want: " + want);
            }
        }
        System.out.println((cases.length - failed) + "/" + cases.length + " cases passed");
        if (failed > 0) System.exit(1);
    }
}

solution.template.go:
package template

import (
	"strconv"
	"strings"
)

const (
	openD   = "<%"
	closeD  = "%>"
	sIf     = "+"
	sNot    = "-"
	sEach   = "*"
	sElse   = ":"
	sEnd    = "/"
	sCmt    = "#"
	hasCond = true
	hasLoop = true
	hasPart = true
	hasPar  = true
	maxDep  = 4
)

var falsy = []string{"", "0", "no"}

type filterDef struct {
	alias, kind string
	takes       bool
}

var filterDefs = []filterDef{{"up", "upper", false}, {"mirror", "rev", false}, {"kebab", "dash", false}, {"ljust", "pad", true}, {"cut", "cut", true}, {"safe", "esc", false}, {"cap", "title", false}, }

type tmplErr struct{ msg string }

type filter struct {
	kind string
	k    int
}

type expr struct {
	ref     string
	filters []filter
	dflt    string
	hasDef  bool
}

type node struct {
	t     string
	s     string
	e     expr
	neg   bool
	then  *[]node
	other *[]node
}

type frame struct {
	parent  *[]node
	other   *[]node
	inElse  bool
}

func fail(m string) { panic(tmplErr{m}) }

func isName(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	if !(c >= 'a' && c <= 'z') && c != '_' {
		return false
	}
	for i := 0; i < len(s); i++ {
		c = s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') && c != '_' {
			return false
		}
	}
	return true
}

func parseData(text string) map[string]string {
	d := map[string]string{}
	for _, line := range strings.Split(text, "\n") {
		if line == "" {
			continue
		}
		ei := strings.IndexByte(line, '=')
		if ei < 0 {
			fail("error: data")
		}
		k, v := line[:ei], line[ei+1:]
		if _, dup := d[k]; !isName(k) || dup {
			fail("error: data")
		}
		var out strings.Builder
		for i := 0; i < len(v); i++ {
			if v[i] == '\\' {
				if i+1 >= len(v) || (v[i+1] != 'n' && v[i+1] != '\\') {
					fail("error: data")
				}
				if v[i+1] == 'n' {
					out.WriteByte('\n')
				} else {
					out.WriteByte('\\')
				}
				i++
			} else {
				out.WriteByte(v[i])
			}
		}
		d[k] = out.String()
	}
	return d
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func parseFilter(tok string) filter {
	if tok == "" {
		fail("error: syntax")
	}
	for i := 0; i < len(tok); i++ {
		if !(tok[i] >= 'a' && tok[i] <= 'z') && !isDigit(tok[i]) {
			fail("error: syntax")
		}
	}
	e := len(tok)
	for e > 0 && isDigit(tok[e-1]) {
		e--
	}
	name, arg := tok[:e], tok[e:]
	if name == "" {
		fail("error: syntax")
	}
	for _, f := range filterDefs {
		if f.alias == name {
			if f.takes {
				if arg == "" || arg[0] == '0' || len(arg) > 2 {
					fail("error: filter " + tok)
				}
				n, _ := strconv.Atoi(arg)
				return filter{f.kind, n}
			}
			if arg != "" {
				fail("error: filter " + tok)
			}
			return filter{f.kind, 0}
		}
	}
	fail("error: filter " + tok)
	return filter{}
}

func parseExpr(c string) expr {
	var x expr
	body := c
	if ei := strings.IndexByte(c, '='); ei >= 0 {
		body = c[:ei]
		x.dflt = c[ei+1:]
		x.hasDef = true
	}
	segs := strings.Split(body, "|")
	x.ref = segs[0]
	ok := isName(x.ref) || (hasLoop && (x.ref == "." || x.ref == "@")) || (hasPar && x.ref == "..")
	if !ok {
		fail("error: syntax")
	}
	if len(segs) > 1 && len(filterDefs) == 0 {
		fail("error: syntax")
	}
	for _, t := range segs[1:] {
		x.filters = append(x.filters, parseFilter(t))
	}
	return x
}

func compile(text string) []node {
	root := []node{}
	cur := &root
	var stack []*frame
	pos := 0
	for {
		i := strings.Index(text[pos:], openD)
		if i < 0 {
			if pos < len(text) {
				*cur = append(*cur, node{t: "text", s: text[pos:]})
			}
			break
		}
		i += pos
		if i > pos {
			*cur = append(*cur, node{t: "text", s: text[pos:i]})
		}
		j := strings.Index(text[i+len(openD):], closeD)
		if j < 0 {
			fail("error: unclosed")
		}
		j += i + len(openD)
		c := text[i+len(openD) : j]
		pos = j + len(closeD)
		switch {
		case c == "":
			*cur = append(*cur, node{t: "text", s: openD})
		case c[0] == sCmt[0]:
		case hasCond && c == sElse:
			if len(stack) == 0 || stack[len(stack)-1].inElse {
				fail("error: unexpected")
			}
			f := stack[len(stack)-1]
			f.inElse = true
			cur = f.other
		case hasCond && c == sEnd:
			if len(stack) == 0 {
				fail("error: unexpected")
			}
			cur = stack[len(stack)-1].parent
			stack = stack[:len(stack)-1]
		case (hasCond && (c[0] == sIf[0] || c[0] == sNot[0])) || (hasLoop && c[0] == sEach[0]):
			n := node{t: "if", e: parseExpr(c[1:]), neg: c[0] == sNot[0], then: &[]node{}, other: &[]node{}}
			if c[0] == sEach[0] {
				n.t = "each"
			}
			*cur = append(*cur, n)
			stack = append(stack, &frame{parent: cur, other: n.other})
			cur = n.then
		case hasPart && c[0] == '>':
			if !isName(c[1:]) {
				fail("error: syntax")
			}
			*cur = append(*cur, node{t: "part", s: c[1:]})
		default:
			*cur = append(*cur, node{t: "var", e: parseExpr(c)})
		}
	}
	if len(stack) > 0 {
		fail("error: unclosed")
	}
	return root
}

func applyFilter(f filter, v string) string {
	switch f.kind {
	case "upper":
		b := []byte(v)
		for i, c := range b {
			if c >= 'a' && c <= 'z' {
				b[i] = c - 32
			}
		}
		return string(b)
	case "lower":
		b := []byte(v)
		for i, c := range b {
			if c >= 'A' && c <= 'Z' {
				b[i] = c + 32
			}
		}
		return string(b)
	case "trim":
		return strings.Trim(v, " ")
	case "len":
		return strconv.Itoa(len(v))
	case "rev":
		b := []byte(v)
		for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
			b[i], b[j] = b[j], b[i]
		}
		return string(b)
	case "pad":
		if len(v) < f.k {
			return v + strings.Repeat(" ", f.k-len(v))
		}
		return v
	case "cut":
		if len(v) > f.k {
			return v[:f.k]
		}
		return v
	case "dash":
		return strings.ReplaceAll(v, " ", "-")
	case "title":
		b := []byte(v)
		prev := byte(' ')
		for i, c := range b {
			if prev == ' ' && c >= 'a' && c <= 'z' {
				b[i] = c - 32
			}
			prev = c
		}
		return string(b)
	case "esc":
		var sb strings.Builder
		for i := 0; i < len(v); i++ {
			switch v[i] {
			case '&':
				sb.WriteString("&amp;")
			case '<':
				sb.WriteString("&lt;")
			case '>':
				sb.WriteString("&gt;")
			case '"':
				sb.WriteString("&quot;")
			default:
				sb.WriteByte(v[i])
			}
		}
		return sb.String()
	}
	panic("bad filter " + f.kind)
}

type loopItem struct {
	item string
	idx  int
}

func evaluate(x expr, loops []loopItem, data map[string]string) string {
	val, have := "", false
	n := len(loops)
	switch x.ref {
	case ".":
		if n >= 1 {
			val, have = loops[n-1].item, true
		}
	case "@":
		if n >= 1 {
			val, have = strconv.Itoa(loops[n-1].idx), true
		}
	case "..":
		if n >= 2 {
			val, have = loops[n-2].item, true
		}
	default:
		val, have = data[x.ref]
	}
	if (!have || val == "") && x.hasDef {
		val, have = x.dflt, true
	}
	if !have {
		fail("error: undefined " + x.ref)
	}
	for _, f := range x.filters {
		val = applyFilter(f, val)
	}
	return val
}

func run(nodes []node, loops []loopItem, depth int, data map[string]string, out *strings.Builder) {
	for _, nd := range nodes {
		switch nd.t {
		case "text":
			out.WriteString(nd.s)
		case "var":
			out.WriteString(evaluate(nd.e, loops, data))
		case "if":
			v := evaluate(nd.e, loops, data)
			truth := true
			for _, f := range falsy {
				if f == v {
					truth = false
				}
			}
			if nd.neg {
				truth = !truth
			}
			if truth {
				run(*nd.then, loops, depth, data, out)
			} else {
				run(*nd.other, loops, depth, data, out)
			}
		case "each":
			v := evaluate(nd.e, loops, data)
			var items []string
			if v != "" {
				items = strings.Split(v, ",")
			}
			if len(items) == 0 {
				run(*nd.other, loops, depth, data, out)
			}
			for ix, it := range items {
				inner := append(append([]loopItem{}, loops...), loopItem{it, ix + 1})
				run(*nd.then, inner, depth, data, out)
			}
		case "part":
			src, ok := data[nd.s]
			if !ok {
				fail("error: undefined " + nd.s)
			}
			if depth+1 > maxDep {
				fail("error: depth")
			}
			run(compile(src), loops, depth+1, data, out)
		}
	}
}

// Render renders a template against data lines.
func Render(tpl, data string) (res string) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(tmplErr); ok {
				res = e.msg
				return
			}
			panic(r)
		}
	}()
	d := parseData(data)
	tree := compile(tpl)
	var out strings.Builder
	run(tree, nil, 0, d, &out)
	return out.String()
}

