package template

import "testing"

func TestCases(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{[]string{"Hello, <%name%>!", "name=Ada\ncity=Oslo"}, "Hello, Ada!"},
		{[]string{"<%city=nowhere%> / <%missing=none%>", "name=Ada"}, "nowhere / none"},
		{[]string{"<%name|up%>", "name=Ada\ncity=Oslo"}, "ADA"},
		{[]string{"<%+flag%>on<%:%>off<%/%> <%-flag%>x<%/%>", "flag=1"}, "on "},
		{[]string{"<%*items%><%@%>=<%.%>; <%:%>nothing<%/%>", "items=ant,bee"}, "1=ant; 2=bee; "},
		{[]string{"<%*items%><%>_row%><%/%>", "items=ant,bee\n_row=<%@%>:<%.%> "}, "1:ant 2:bee "},
	}
	for i, c := range cases {
		got := Render(c.in[0], c.in[1])
		if got != c.want {
			t.Errorf("case %d %q:\n got  %q\n want %q", i, c.in, got, c.want)
		}
	}
}
